 d=deepcopy(D['decisions'][cid]);ca=dict(name=name,media=['game'],scope=scope,axis=dict(zip(('guarantees','control','nonworking'),values)),intervals=dict(zip(('guarantees','control','nonworking'),bounds)),confidence='low',canon_facts=facts,editorial_assumptions=assumptions,source_ids=d['source_ids'],counted_toward_goal=False)
